GLOSSARY = [
 ("APR (Annual Percentage Rate)","The yearly cost of a loan including interest and mandatory charges, shown as one percentage. Useful for comparing offers."),
 ("EMI","Equated Monthly Instalment: the fixed amount paid each month, containing both principal and interest."),
 ("Principal","The original amount borrowed, excluding interest."),
 ("Tenure","The total period over which the loan is repaid."),
 ("Collateral","An asset pledged to secure a loan, such as property, gold or securities."),
 ("Secured loan","A loan backed by collateral."),
 ("Unsecured loan","A loan not backed by collateral, such as most personal loans."),
 ("Credit score","A three-digit number, typically 300 to 900, summarising your creditworthiness."),
 ("Credit report","A detailed record of your credit accounts and repayment history, from a credit bureau."),
 ("CIBIL","A well-known credit information company in India, often used as a general term for credit score."),
 ("FOIR","Fixed Obligations to Income Ratio: the share of your income that goes to EMIs and fixed obligations."),
 ("LTV","Loan-to-Value ratio: the loan amount as a percentage of the asset's value."),
 ("KFS (Key Fact Statement)","A standard statement of the main loan terms, including APR and charges, that lenders must provide under RBI digital lending rules."),
 ("NBFC","Non-Banking Financial Company, a financial institution regulated by RBI that lends but does not hold a banking licence."),
 ("HFC","Housing Finance Company, an NBFC focused on housing loans."),
 ("DSA","Direct Selling Agent: an intermediary who sources loan customers for lenders."),
 ("LSP","Lending Service Provider: an agent of a regulated lender that performs functions like customer acquisition or servicing."),
 ("Balance transfer","Moving an existing loan to another lender, usually for a lower rate."),
 ("Top-up loan","An additional loan on top of an existing loan, typically at similar terms."),
 ("Foreclosure","Closing a loan fully before its scheduled end."),
 ("Part-prepayment","Paying a lump sum towards principal before the due date."),
 ("Moratorium","A period during which full repayment is paused, such as the course period in an education loan."),
 ("Cooling-off period","A window after disbursal during which a borrower can exit a loan by repaying principal and proportionate interest, under RBI digital lending rules."),
 ("Co-applicant","A second person applying with you, whose income and credit are considered. Both are legally liable."),
 ("Guarantor","A person who agrees to repay if the borrower defaults."),
 ("Hypothecation","Pledging a movable asset, such as a vehicle, as security without handing over possession."),
 ("Mortgage","A legal charge on immovable property as security for a loan."),
 ("Encumbrance certificate","A document showing whether a property has any legal dues or pending mortgages."),
 ("Processing fee","A one-time charge by the lender for evaluating and processing the loan."),
 ("Sanction letter","The lender's written approval stating the loan amount, rate, tenure and terms."),
 ("Disbursal","The release of the loan amount to the borrower."),
 ("Overdraft","A revolving facility that lets you withdraw more than your balance up to a limit."),
 ("Cash credit","A working-capital limit against stock and receivables."),
 ("Udyam","The government registration for micro, small and medium enterprises."),
 ("GST","Goods and Services Tax, used by lenders as a source of business turnover data."),
 ("SARFAESI Act","A law that allows secured lenders to recover dues by enforcing security without court intervention, subject to conditions."),
 ("Floating rate","An interest rate linked to a benchmark that can change over time."),
 ("Fixed rate","An interest rate that stays the same for an agreed period."),
 ("Repo rate","The rate at which RBI lends to banks, widely used as a benchmark for floating-rate retail loans."),
 ("BNPL","Buy Now, Pay Later: a short-term credit product that lets you purchase now and pay later."),
 ("TReDS","Trade Receivables Discounting System: an RBI-regulated platform for discounting MSME invoices."),
 ("Letter of credit","A bank's undertaking to pay a seller on presentation of compliant documents."),
]

